#!/bin/bash
cd "$(dirname "$0")/../.."
node scripts/portraits/select-source.js --slug john-wall --url 'https://upload.wikimedia.org/wikipedia/commons/9/96/John_Wall_%2831692313715%29.jpg' --page 'https://commons.wikimedia.org/wiki/File:John_Wall_(31692313715).jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison' --date '2016-12-16 (Pistons at Wizards, Verizon Center)' --crop 1070,830,760 --scores 3,3,3,1,2,2,1 --energy 7 --vs-mccain 'matches (eyes up on the ball at the end of a layup, mouth open mid-breath)' --jersey 'WAS navy road "Washington" 2016-17' --concerns 'his own shooting hand at the bottom edge of the crop; mid-layup so head tilted slightly up; face ~340px' --alt 'https://upload.wikimedia.org/wikipedia/commons/1/1a/John_Wall_%2832487068492%29.jpg (Jan 31 2017 vs NYK, white home, mouth open looking up mid-layup, energy ~7.5, arm extended across frame)' --alt 'https://upload.wikimedia.org/wikipedia/commons/9/99/John_Wall_2017_%28cropped%29.jpg (2017 white home, dribbling, looking off with mouth closed, energy ~5.5)'
node scripts/portraits/select-source.js --slug otto-porter-jr --url 'https://upload.wikimedia.org/wikipedia/commons/d/d6/Isaiah_Thomas%2C_Otto_Porter_Jr._%2834419856896%29.jpg' --page 'https://commons.wikimedia.org/wiki/File:Isaiah_Thomas,_Otto_Porter_Jr._(34419856896).jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison' --date '2017-05-04 (2017 East semifinals Game 3, Celtics at Wizards, Verizon Center)' --crop 1040,0,800 --scores 3,3,3,1,2,2,1 --energy 6.5 --vs-mccain 'matches (holding the ball away from Isaiah Thomas, eyes off-camera, lips drawn back showing teeth)' --jersey 'WAS white home "Washington" 2016-17 (2017 playoffs)' --concerns 'expression is half grin, half effort grimace; his own shoulder and the ball sit in the lower and right edges of the crop; Isaiah Thomas reaching in below, outside the crop' --alt 'https://upload.wikimedia.org/wikipedia/commons/e/eb/Markieff_Morris%2C_Otto_Porter_Jr._%2834138344010%29.jpg (May 7 2017 G4 vs BOS, white home, standing with Markieff Morris, relaxed grin looking off, energy ~6, 3/4 face)' --alt 'https://upload.wikimedia.org/wikipedia/commons/9/97/Otto_Porter_Jr._%2833617658194%29.jpg (May 4 2017 G3 vs BOS, white home, going up for a rebound, teeth bared straining, energy ~8.5)'
node scripts/portraits/select-source.js --slug kirk-hinrich --url 'https://upload.wikimedia.org/wikipedia/commons/3/33/Kirk_Hinrich-crop.jpg' --page 'https://commons.wikimedia.org/wiki/File:Kirk_Hinrich-crop.jpg' --license 'CC BY-SA 4.0 / GFDL' --author 'Jauerback' --date '2008-01-25 (2007-08 season, United Center; extracted from File:Kirk_Hinrich_(2).jpg)' --crop 125,0,560 --scores 2,2,3,1,2,2,1 --energy 7 --vs-mccain 'matches (standing on court during a stop, looking off-camera, mouth open mid-reaction)' --jersey 'CHI white home #12, 2007-08 (one season after the wanted 2006-07)' --concerns 'face ~270px but soft (2008 consumer DSLR, native-resolution extract); lower lip curled showing teeth, slightly quizzical; a courtside fan face at the left edge of the crop' --alt 'https://upload.wikimedia.org/wikipedia/commons/d/d5/Kirk_Hinrich.jpg (Feb 27 2009 at WAS, CHI red road, driving, face ~150px, Noah and Wizards defender in frame)' --alt 'https://upload.wikimedia.org/wikipedia/commons/4/44/Kirk_Hinrich_vs_Bucks.jpg (Feb 18 2009 at MIL, CHI black alternate, passing, small face, looking down, energy ~4)'
node scripts/portraits/select-source.js --slug victor-oladipo --url 'https://upload.wikimedia.org/wikipedia/commons/5/5d/Victor_Oladipo_%2839060269840%29.jpg' --page 'https://commons.wikimedia.org/wiki/File:Victor_Oladipo_(39060269840).jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison' --date '2018-03-17 (Pacers at Wizards, Capital One Arena)' --crop 660,970,760 --scores 3,3,3,1,2,2,1 --energy 7 --vs-mccain 'matches (eyes up on the ball at the end of a layup, mouth open mid-breath)' --jersey 'IND gold Statement #4, 2017-18' --concerns 'his raised shooting arm runs up the left side of the crop with hand and ball in the top-left corner; head tilted up; face ~250px in the stored 3000px image' --alt 'https://upload.wikimedia.org/wikipedia/commons/0/03/Victor_Oladipo_%2840829042322%29.jpg (same game, gold, mouth wide and brow knit gathering for a layup, energy ~8.5, hand and ball beside the face)' --alt 'https://upload.wikimedia.org/wikipedia/commons/9/9e/Victor_Oladipo_%2839060706270%29.jpg (same game, gold, free throw, large sharp face but calm closed-mouth focus, energy ~5.5, ball and hand at right)'
node scripts/portraits/select-source.js --slug eric-bledsoe --url 'https://upload.wikimedia.org/wikipedia/commons/0/0d/Bradley_Beal%2C_Eric_Bledsoe_%2827935025389%29.jpg' --page 'https://commons.wikimedia.org/wiki/File:Bradley_Beal,_Eric_Bledsoe_(27935025389).jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison' --date '2018-01-15 (Bucks at Wizards, Capital One Arena)' --crop 1300,150,850 --scores 3,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'matches (pushing the ball upcourt, eyes off-camera, mouth open mid-breath)' --jersey 'MIL white Association #6, 2017-18 (same team, one season before the wanted 2018-19)' --concerns 'Bradley Beal tattooed arm at the far left edge of the crop; slight high-ISO noise; face ~370px' --alt 'https://upload.wikimedia.org/wikipedia/commons/d/d7/Eric_Bledsoe_Suns.jpg (Jan 12 2017 in Mexico City, PHX, only 688x781, not MIL)'
node scripts/portraits/select-source.js --slug leandro-barbosa --url 'https://upload.wikimedia.org/wikipedia/commons/e/e6/Leonardo_barbosa_free.jpg' --page 'https://commons.wikimedia.org/wiki/File:Leonardo_barbosa_free.jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison' --date '2007-12-08 (Suns road game, 2007-08 season)' --crop 330,680,780 --scores 3,3,1,1,2,2,1 --energy 5.5 --vs-mccain 'lower (at the free-throw line, eyes up at the rim, lips pushed out blowing out a breath)' --jersey 'PHX purple road #10, 2007-08 (one season after the wanted 2006-07)' --concerns 'FLAG: pursed-lips exhale reads oddly and sits below the 6-8 band; both shooting arms frame the head (black sleeve on the right edge); no sharper in-band PHX game photo found on Commons or nba.com (Suns legacy galleries only carry 500px copies)' --needs-review 'energy ~5.5 with a pursed-lips free-throw face; best sharp in-game PHX source found' --alt 'https://upload.wikimedia.org/wikipedia/commons/8/83/Lbarbosa.jpg (PD, Apr 6 2008, PHX white home, dribbling and looking off, energy ~5, face ~245px, grainy and blown-out color)' --alt 'https://cdn.nba.com/teams/legacy/www.nba.com/suns/sites/suns/files/legacy/photos/r2g3_barbosa_06playoffs.jpg (2006 West semis G3 at LAC, PHX purple, driving, energy ~6.5, but a 415x500 web copy with a ~60px face)'
node scripts/portraits/select-source.js --slug kelly-olynyk --url 'https://cloudfront-us-east-1.images.arcpublishing.com/sltrib/RFXKLZ2HCJEAJBVE6QKWGM74EI.jpg' --page 'https://www.sltrib.com/sports/jazz/2023/11/12/nba-foodies-like-jazzs-kelly/' --license 'unknown (The Salt Lake Tribune)' --author 'Trent Nelson / The Salt Lake Tribune' --date '2023-10-27 (Clippers at Jazz, Delta Center)' --crop 1380,120,1250 --scores 3,3,3,2,2,2,1 --energy 7.5 --vs-mccain 'slightly higher (passing the ball, looking off-camera, mouth open with teeth showing mid-call)' --jersey 'UTA black Icon #41, 2023-24' --concerns 'mouth open wide enough to show both rows of teeth, at the top of the band; headband; his passing arm crosses the lower left of the crop (ball outside it)' --alt 'https://cdn.nba.com/manage/2024/02/USATSI_22346863-scaled-e1707410961195.jpg (USA Today via nba.com trade story, UTA black 2023-24 at HOU, big open-mouth laugh jogging upcourt, energy ~8.5)'
node scripts/portraits/select-source.js --slug joe-johnson --url 'https://assets-cms.thescore.com/uploads/image/file/116845/REUA_048527.jpg' --page 'https://www.thescore.com/nba/news/768396' --license 'unknown (Reuters via theScore)' --author 'Reuters' --date 'undated, c. 2002-05 (Suns at Grizzlies, FedExForum era)' --crop 760,0,780 --scores 2,3,2,2,2,2,1 --energy 8 --vs-mccain 'higher (arguing a call with arms spread, squinting, mouth twisted open)' --jersey 'PHX purple road #2, c. 2002-05 (exact season unverified)' --concerns 'FLAG: complaint face with a squint, at the top edge of the band; high-ISO grain and soft focus; exact date unknown (Reuters file, no caption found); spread arms and a Grizzlies player are outside the crop' --needs-review 'energy ~8 squinting complaint face, soft/grainy, undated; the only sizable in-game PHX photo found (Commons has no Suns-era Johnson; Suns legacy galleries are 500px)' --alt 'https://upload.wikimedia.org/wikipedia/commons/5/53/Joe_Johnson_Mar-2012.jpg (CC BY-SA 2.0 Keith Allison, Mar 24 2012, ATL red road, rebounding with mouth wide open, energy ~8.5, raised arm across the left of the crop, not PHX)'
